static lstr L1131 = {0, 5278, "// std/arena: values in slots, reached through generation-checked handles.\012//\012// A graph with cycles keeps its nodes in an Arena and refers to them with\012// Handle values. A handle is a slot index and the generation the slot had when\012// the value went in. Removing a value, or clearing the arena, raises the\012// generation, so an old handle finds nothing. A handle from another arena is\012// not detected: it reads whatever that slot of this arena holds.\012\012import * as Arrays from \"std/array\"\012\012/// A reference to one value of an `Arena<T>` that finds nothing once the value is removed.\012/// A handle used with another arena is not caught, and reads the same slot there.\012export opaque struct Handle<T> derives Equatable, Hashable, Show {\012  index: int\012  generation: int\012}\012\012/// Values of type `T` in numbered slots, each reached through the `Handle<T>` that `insert` gave.\012export opaque struct Arena<T> {\012  slots: Array<Option<T>>\012  generations: Array<int>\012  free: Array<int>\012  freeCount: int\012  count: int\012}\012\012/// Creates an empty arena.\012export function create<T>(): Arena<T> uses alloc {\012  return Arena<T> { slots: [], generations: [], free: [], freeCount: 0, count: 0 }\012}\012\012/// Stores value in a free slot, or in a new one, and returns its handle.\012export function insert<T>(mutable arena: Arena<T>, value: T): Handle<T> uses alloc {\012  // Reuse the last freed slot, or add a new one.\012  if (arena.freeCount > 0) {\012    arena.freeCount = arena.freeCount - 1\012    const index = arena.free[arena.freeCount]\012    arena.slots[index] = Some(value)\012    arena.count = arena.count + 1\012    return Handle<T> { index, generation: arena.generations[index] }\012  }\012  const index = Arrays.length(arena.slots)\012  Arrays.push(mutable arena.slots, Some(value))\012  Arrays.push(mutable arena.generations, 0)\012  arena.count = arena.count + 1\012  return Handle<T> { index, generation: 0 }\012}\012\012function pushFree<T>(mutable arena: Arena<T>, index: int) uses alloc {\012  // The free list is a stack: freeCount says how many entries are in use.\012  if (arena.freeCount < Arrays.length(arena.free)) {\012    arena.free[arena.freeCount] = index\012  } else {\012    Arrays.push(mutable arena.free, index)\012  }\012  arena.freeCount = arena.freeCount + 1\012}\012\012function isLive<T>(arena: Arena<T>, handle: Handle<T>): bool {\012  if (handle.index < 0 || handle.index >= Arrays.length(arena.slots)) {\012    return false\012  }\012  if (arena.generations[handle.index] != handle.generation) {\012    return false\012  }\012  return arena.slots[handle.index] is Some(_)\012}\012\012/// Tells whether the handle still finds a value in the arena.\012export function contains<T>(arena: Arena<T>, handle: Handle<T>): bool {\012  return isLive(arena, handle)\012}\012\012/// Returns the number of values the arena holds.\012export function size<T>(arena: Arena<T>): int {\012  return arena.count\012}\012\012/// Returns the value of the handle, or `None` once it was removed or the arena was cleared.\012export function get<T>(arena: Arena<T>, handle: Handle<T>): Option<T> from arena {\012  if (!isLive(arena, handle)) {\012    return None\012  }\012  return arena.slots[handle.index]\012}\012\012/// Replaces the value of the handle and returns `true`, or returns `false` and stores nothing when\012/// the handle finds no value.\012export function set<T>(mutable arena: Arena<T>, handle: Handle<T>, value: T): bool {\012  if (!isLive(arena, handle)) {\012    return false\012  }\012  arena.slots[handle.index] = Some(value)\012  return true\012}\012\012/// Replaces the value of the handle with `change(value)` and returns `true`, or returns `false`\012/// without calling change when the handle finds no value.\012export function update<T, effect E>(\012  mutable arena: Arena<T>,\012  handle: Handle<T>,\012  change: (value: T) => T uses E,\012): bool uses E {\012  if (!isLive(arena, handle)) {\012    return false\012  }\012  // Take the value out first, so the change works on a unique value.\012  const old = arena.slots[handle.index]\012  arena.slots[handle.index] = None\012  if (old is Some(value)) {\012    arena.slots[handle.index] = Some(change(value))\012  }\012  return true\012}\012\012/// Takes the value of the handle out of the arena, or returns `None` when the handle finds none.\012/// The handle and every copy of it then find nothing.\012export function remove<T>(mutable arena: Arena<T>, handle: Handle<T>): Option<T> uses alloc {\012  if (!isLive(arena, handle)) {\012    return None\012  }\012  const old = arena.slots[handle.index]\012  arena.slots[handle.index] = None\012  arena.generations[handle.index] = handle.generation + 1\012  pushFree(mutable arena, handle.index)\012  arena.count = arena.count - 1\012  return copy(old)\012}\012\012/// Removes every value, so no handle given before finds anything.\012export function clear<T>(mutable arena: Arena<T>) uses alloc {\012  // Keep the slots and raise every generation, so no old handle matches.\012  arena.freeCount = 0\012  arena.count = 0\012  for (let index = 0; index < Arrays.length(arena.slots); index = index + 1) {\012    arena.slots[index] = None\012    arena.generations[index] = arena.generations[index] + 1\012    pushFree(mutable arena, index)\012  }\012}\012\012/// Yields each handle and its value, in slot order.\012export function* entries<T>(arena: Arena<T>): Generator<#[Handle<T>, T]> {\012  for (let index = 0; index < Arrays.length(arena.slots); index = index + 1) {\012    if (arena.slots[index] is Some(value)) {\012      yield #[Handle<T> { index, generation: arena.generations[index] }, value]\012    }\012  }\012}\012"};
