static lstr L1139 = {0, 1978, "// std/build: the target a program is built for. The compiler sets os, arch and\012// debug for each build; the values written here are replaced. An `if` that\012// tests only these constants keeps one branch in the output.\012\012import * as Host from \"std/internal/host\"\012\012/// The operating systems a program can be built for.\012export enum Os derives Show, Equatable {\012  MacOS\012  Linux\012  Windows\012  Wasi\012}\012\012/// The processor architectures a program can be built for.\012export enum Arch derives Show, Equatable {\012  Arm64\012  X86_64\012  Wasm32\012}\012\012/// The operating system of the build target. The compiler sets it for each build, so an `if` on\012/// it keeps only one branch.\012export const os: Os = Os.Linux\012\012/// The architecture of the build target. The compiler sets it for each build, so an `if` on it\012/// keeps only one branch.\012export const arch: Arch = Arch.X86_64\012\012/// Tells whether this is a debug build: `true` by default and `false` in a `-release` build.\012export const debug: bool = true\012\012/// An operating system and an architecture.\012export struct Target {\012  os: Os\012  arch: Arch\012}\012\012/// Gives the target the C compiler built this program for, or `None` on a system that `Os` and\012/// `Arch` do not list, such as WASI.\012export function hostTarget(): Option<Target> {\012  const hostOs = Host.os()\012  const hostArch = Host.arch()\012  // The C compiler's predefined macros give the codes; 0 is a machine with no variant here.\012  if (hostOs == 0 || hostArch == 0) {\012    return None\012  }\012  if (hostOs == 1 && hostArch == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.Arm64 })\012  }\012  if (hostOs == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.X86_64 })\012  }\012  if (hostOs == 3 && hostArch == 1) {\012    return Some(Target { os: Os.Windows, arch: Arch.Arm64 })\012  }\012  if (hostOs == 3) {\012    return Some(Target { os: Os.Windows, arch: Arch.X86_64 })\012  }\012  if (hostArch == 1) {\012    return Some(Target { os: Os.Linux, arch: Arch.Arm64 })\012  }\012  return Some(Target { os: Os.Linux, arch: Arch.X86_64 })\012}\012"};
