static lstr L1147 = {0, 1690, "// std/cstring: CString, a string with no zero byte, which C reads as a zero-terminated string.\012//\012// Pass `CStrings.pointer(text)` to a C function that takes `char*`; the pointer is valid while\012// the CString is. `CStrings.read` copies a zero-terminated string that C returns.\012\012import * as Bytes from \"std/bytes\"\012import * as Str from \"std/string\"\012import * as Ptr from \"std/ptr\"\012import * as Text from \"std/internal/cstring\"\012\012/// A string with no zero byte, which a C function can read as a zero-terminated string.\012export opaque struct CString {\012  text: string\012}\012\012/// Returns the text as a `CString`, or `None` when it holds a zero byte.\012export function from(text: string): Option<CString> {\012  // C would stop at a zero byte, so a string that holds one has no CString.\012  const length = Str.length(text)\012  for (let index = 0; index < length; index++) {\012    if (Str.byteAt(text, index) == 0) {\012      return None\012    }\012  }\012  return Some(CString { text })\012}\012\012/// Returns the text of the `CString`.\012export function toString(value: CString): string from value {\012  return value.text\012}\012\012/// Returns a pointer to the zero-terminated text, for a C function that takes `char*`. The\012/// pointer is valid only while the `CString` is.\012export function pointer(value: CString): Ptr<u8> {\012  return Text.pointer(value.text)\012}\012\012/// Copies the zero-terminated string at `address` into a new string, or gives an error when it\012/// is not valid UTF-8. `address` must point to a zero-terminated string.\012export function read(address: Ptr<u8>): Result<string, string> uses alloc, unsafe {\012  let copied: Result<string, string> = Err(\"\")\012  unsafe {\012    copied = Bytes.toString(Text.read(address))\012  }\012  return copied\012}\012"};
