static lstr L1155 = {0, 1580, "// std/char: code points and ASCII classes. The conversion functions are built into the compiler.\012//\012// The classes cover ASCII only: a character above U+007F is in none of them, and\012// isWhitespace is true for the six ASCII white space characters that Str.trim removes.\012\012import * as Char from \"std/char\"\012\012/// Tells whether the character is an ASCII digit, `0` to `9`.\012export function isDigit(character: char): bool {\012  const code = Char.code(character)\012  return code >= 48 && code <= 57\012}\012\012/// Tells whether the character is an ASCII capital letter, `A` to `Z`. Letters outside ASCII\012/// give false.\012export function isUpper(character: char): bool {\012  const code = Char.code(character)\012  return code >= 65 && code <= 90\012}\012\012/// Tells whether the character is an ASCII small letter, `a` to `z`. Letters outside ASCII give\012/// false.\012export function isLower(character: char): bool {\012  const code = Char.code(character)\012  return code >= 97 && code <= 122\012}\012\012/// Tells whether the character is an ASCII letter. Letters outside ASCII give false.\012export function isLetter(character: char): bool {\012  return isUpper(character) || isLower(character)\012}\012\012/// Tells whether the character is an ASCII letter or digit.\012export function isAlphanumeric(character: char): bool {\012  return isLetter(character) || isDigit(character)\012}\012\012/// Tells whether the character is ASCII white space: space, tab, line feed, vertical tab, form\012/// feed or carriage return.\012export function isWhitespace(character: char): bool {\012  const code = Char.code(character)\012  return code == 32 || (code >= 9 && code <= 13)\012}\012"};
