static lstr L1165 = {0, 565, "// std/fixedarray: helpers over FixedArray. An index written as values[i] must be\012// proven in range; get checks the index and returns None outside it.\012\012/// Returns the value at index, or `None` when index is outside 0 to `N - 1`.\012export function get<T, const N: int>(values: FixedArray<T, N>, index: int): Option<T> from values {\012  if (index >= 0 && index < N) {\012    return Some(values[index])\012  }\012  return None\012}\012\012/// Returns `N`, the length that is part of the array's type.\012export function length<T, const N: int>(_values: FixedArray<T, N>): int {\012  return N\012}\012"};
