static lstr L1179 = {0, 8469, "// std/net: TCP sockets on the loop of the thread.\012//\012// listen and localPort do not suspend. accept, connect, read and write wait in\012// the loop until the socket is ready, so the other tasks run meanwhile. A\012// Listener or a Connection is a handle: copies share the socket, and it\012// closes when the last copy is dropped. listen takes a numeric IPv4 or IPv6\012// address; lookup and connect also take a host name, which the system resolver\012// answers on a helper thread so the loop keeps running.\012\012import * as Arrays from \"std/array\"\012import * as Bytes from \"std/bytes\"\012import * as Str from \"std/string\"\012import * as Handles from \"std/internal/asyncio\"\012import { AsyncError } from \"std/async\"\012\012/// A listening TCP socket. Copies share the socket, which closes when the last copy is dropped.\012export opaque struct Listener {\012  handle: Handle\012}\012\012/// A connected TCP socket. Copies share the socket, which closes when the last copy is dropped.\012export opaque struct Connection {\012  handle: Handle\012}\012\012function failWith(code: int): AsyncError uses alloc {\012  return AsyncError.Failed(Handles.message(code))\012}\012\012// The error of a wait that ended with ready: None when the socket is ready.\012// Each suspending function waits itself, never through a helper task, so a\012// cancel of the task that awaits it reaches the wait. One task at a time may\012// wait in each direction; busy names what the other task already does.\012function checkWait(ready: int, busy: string): Option<AsyncError> uses alloc {\012  if (ready < 0) {\012    return Some(AsyncError.Cancelled)\012  }\012  if (Handles.busy(ready)) {\012    return Some(AsyncError.Failed(`another task is already ${busy}`))\012  }\012  if (ready > 0) {\012    return Some(failWith(ready))\012  }\012  return None\012}\012\012/// A socket that accepts connections on host and port. host is a numeric IPv4 or IPv6 address,\012/// not a name. Port 0 picks a free port, which localPort gives.\012export function listen(host: string, port: int): Result<Listener, AsyncError> uses io, alloc {\012  const handle = Handles.listen(host, port)\012  const code = Handles.error()\012  if (code != 0) {\012    return Err(failWith(code))\012  }\012  return Ok(Listener { handle })\012}\012\012/// The port the listener is bound to.\012export function localPort(listener: Listener): int uses io {\012  return Handles.localPort(listener.handle)\012}\012\012/// The next connection to the listener, waiting until one comes. A cancel ends the wait with\012/// Err(AsyncError.Cancelled).\012export async function accept(listener: Listener): Result<Connection, AsyncError> uses io, alloc {\012  while (true) {\012    if (Handles.cancelled()) {\012      return Err(AsyncError.Cancelled)\012    }\012    const handle = Handles.accept(listener.handle)\012    const code = Handles.error()\012    if (code == 0) {\012      return Ok(Connection { handle })\012    }\012    // A connection that went before it was taken leaves the others to accept.\012    if (!Handles.acceptAgain(code)) {\012      if (!Handles.retry(code)) {\012        return Err(failWith(code))\012      }\012      const problem = checkWait(\012        await Handles.wait(listener.handle, false),\012        \"accepting on this listener\",\012      )\012      if (problem is Some(error)) {\012        return Err(error)\012      }\012    }\012  }\012}\012\012/// The addresses of host, as numeric IPv6 and IPv4 text in the order of the system resolver\012/// (getaddrinfo, so /etc/hosts and the system DNS settings apply). A numeric host is returned as\012/// it is, with no lookup. The lookup runs on a helper thread, so other tasks keep running, and a\012/// cancel ends the wait at once with Err(AsyncError.Cancelled). A name with no address gives\012/// Err(AsyncError.Failed(...)); so does any name on a platform with no resolver (WASI, Windows).\012export async function lookup(host: string): Result<Array<string>, AsyncError> uses io, alloc {\012  if (Handles.isNumeric(host)) {\012    return Ok([host])\012  }\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const handle = Handles.lookup(host)\012  const code = Handles.error()\012  if (code != 0) {\012    return Err(failWith(code))\012  }\012  const problem = checkWait(await Handles.wait(handle, false), \"looking up this host\")\012  if (problem is Some(error)) {\012    return Err(error)\012  }\012  const text = Handles.lookupResult(handle)\012  if (Handles.error() != 0) {\012    return Err(AsyncError.Failed(`cannot look up ${host}: ${text}`))\012  }\012  const lines = Str.split(text, \"\\n\")\012  if (lines is Some(addresses)) {\012    return Ok(addresses)\012  }\012  return Ok([text])\012}\012\012/// A connection to host and port, once the peer accepts it. host is a numeric IPv4 or IPv6\012/// address or a host name. A name is looked up first (see lookup), and each address is tried in\012/// turn until one accepts; the error of the last attempt is the result when none does.\012export async function connect(\012  host: string,\012  port: int,\012): Result<Connection, AsyncError> uses io, alloc {\012  if (Handles.isNumeric(host)) {\012    return await connectAddress(host, port)\012  }\012  const found = await lookup(host)\012  if (found is Err(error)) {\012    return Err(error)\012  }\012  let lastError = AsyncError.Failed(`no address for ${host}`)\012  for (const address of Arrays.values(found.value)) {\012    const attempt = await connectAddress(address, port)\012    if (attempt is Err(error)) {\012      if (error is AsyncError.Cancelled) {\012        return attempt\012      }\012      lastError = error\012    } else {\012      return attempt\012    }\012  }\012  return Err(lastError)\012}\012\012async function connectAddress(\012  host: string,\012  port: int,\012): Result<Connection, AsyncError> uses io, alloc {\012  // One connect to a numeric address.\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const handle = Handles.connect(host, port)\012  const code = Handles.error()\012  if (code == 0) {\012    return Ok(Connection { handle })\012  }\012  if (!Handles.pending(code)) {\012    return Err(failWith(code))\012  }\012  const problem = checkWait(await Handles.wait(handle, true), \"connecting this socket\")\012  if (problem is Some(error)) {\012    return Err(error)\012  }\012  const result = Handles.connected(handle)\012  if (result != 0) {\012    return Err(failWith(result))\012  }\012  return Ok(Connection { handle })\012}\012\012/// Up to maxBytes bytes from the connection, at most 64 KiB, once some are\012/// there. Empty bytes mean the peer has closed its side; a maxBytes of zero or\012/// less gives empty bytes at once.\012export async function read(\012  connection: Connection,\012  maxBytes: int,\012): Result<bytes, AsyncError> uses io, alloc {\012  while (true) {\012    if (Handles.cancelled()) {\012      return Err(AsyncError.Cancelled)\012    }\012    const data = Handles.read(connection.handle, maxBytes)\012    const code = Handles.error()\012    if (code == 0) {\012      return Ok(data)\012    }\012    if (!Handles.retry(code)) {\012      return Err(failWith(code))\012    }\012    const problem = checkWait(\012      await Handles.wait(connection.handle, false),\012      \"reading this connection\",\012    )\012    if (problem is Some(error)) {\012      return Err(error)\012    }\012  }\012}\012\012/// The reads of the connection as a stream: Ok(chunk) for each read of up to\012/// maxBytes bytes, until the peer closes its side. An error gives one Err, and\012/// then the stream ends, so a reader can tell the end from a failure. A\012/// maxBytes of zero or less ends the stream at once, as read gives empty bytes.\012export async function* chunks(\012  connection: Connection,\012  maxBytes: int,\012): AsyncGenerator<Result<bytes, AsyncError>> uses (io, alloc) {\012  while (true) {\012    const result = await read(connection, maxBytes)\012    if (result is Ok(chunk)) {\012      if (Bytes.length(chunk) == 0) {\012        return\012      }\012      yield Ok(chunk)\012    } else {\012      yield result\012      return\012    }\012  }\012}\012\012/// Writes every byte of data and gives the count. A cancel while it waits\012/// ends it with Err(AsyncError.Cancelled), whatever part was sent.\012export async function write(\012  connection: Connection,\012  data: bytes,\012): Result<int, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  let sent = 0\012  const total = Bytes.length(data)\012  // A wait that a cancel ends gives -1, so the loop needs no second check.\012  while (sent < total) {\012    const count = Handles.write(connection.handle, data, sent)\012    const code = Handles.error()\012    if (code == 0) {\012      sent += count\012    } else if (!Handles.retry(code)) {\012      return Err(failWith(code))\012    } else {\012      const problem = checkWait(\012        await Handles.wait(connection.handle, true),\012        \"writing this connection\",\012      )\012      if (problem is Some(error)) {\012        return Err(error)\012      }\012    }\012  }\012  return Ok(sent)\012}\012"};
