static lstr L7443 = {0, 397, "\012// Dynamic values\012typedef struct narra_dyn { int64_t rc; const void* table; } narra_dyn;\012typedef struct narra_dyn_table { void (*drop)(void* cell); } narra_dyn_table;\012static void narra_dyn_retain(narra_dyn* d) {\012  d->rc++;\012  NARRA_COPY_SHARED(d);\012}\012static void narra_dyn_release(narra_dyn* d) {\012  NARRA_COPY_DROP(d);\012  if (--d->rc == 0) narra_drop(d, ((const narra_dyn_table*)d->table)->drop);\012}\012"};
